package org.sleepwell.app;
import android.content.*;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.Test;
import java.time.*;
import java.util.*;
import static org.junit.Assert.*;

/** Isolated preferences only; no services, output provider, clock changes or hardware. */
public class TravelCueStorageTest {
 final Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();final long now=Instant.parse("2026-10-23T12:00:00Z").toEpochMilli();
 final class Fixture implements AutoCloseable {final String name="travel-cue-storage-"+UUID.randomUUID();final SharedPreferences prefs=c.getSharedPreferences(name,0);final TravelPlans.Repository repo=new TravelPlans.Repository(prefs);final TravelCueStore cues=new TravelCueStore(prefs);TravelPlan trip(){TravelPlan t=repo.load(now);t.home="Asia/Riyadh";t.destination="Europe/London";t.departure=LocalDate.of(2026,10,27);return t;}TravelCuePlan cue(TravelPlan t){return new TravelCuePlan(0,t.revision,true,true,t.home,t.destination,LocalDate.of(2026,10,23),1320,30,2);}public void close(){assertTrue(prefs.edit().clear().commit());assertTrue(c.deleteSharedPreferences(name));}}
 @Test public void saveIsAtomicAndStaleCueOrTripCannotReplaceNewerSettings(){try(Fixture f=new Fixture()){TravelPlan draft=f.trip();TravelCuePlan first=f.cue(draft);f.repo.save(draft,first,now);TravelPlan saved=f.repo.load(now);TravelCuePlan savedCue=f.cues.load(saved,now);assertEquals(saved.revision,savedCue.tripRevision);assertTrue(savedCue.enabled);Map<String,?> before=f.prefs.getAll();try{f.repo.save(saved,first,now+1);fail();}catch(IllegalArgumentException expected){}assertEquals(before,f.prefs.getAll());TravelPlan stale=f.trip();stale.revision=0;try{f.repo.save(stale,savedCue,now+2);fail();}catch(IllegalArgumentException expected){}assertEquals(before,f.prefs.getAll());}}
 @Test public void strictCodecRejectsCoercionAndUnknownKeysWithoutWriting()throws Exception{try(Fixture f=new Fixture()){TravelCuePlan plan=f.cue(f.trip());JSONObject good=TravelCueJson.encode(plan);assertEquals(plan.minute,TravelCueJson.decode(good).minute);for(JSONObject bad:new JSONObject[]{new JSONObject(good.toString()).put("minute","1320"),new JSONObject(good.toString()).put("minute",1320.5),new JSONObject(good.toString()).put("enabled",1),new JSONObject(good.toString()).put("extra",true),new JSONObject(good.toString()).put("first","2026-1-1"),new JSONObject(good.toString()).put("reviewed",false)}){try{TravelCueJson.decode(bad);fail(bad.toString());}catch(JSONException expected){}}assertTrue(f.prefs.getAll().isEmpty());}}
 @Test public void newerJournalOwnerRejectsLateOldTerminalOrReleaseFailure(){try(Fixture f=new Fixture()){String first=UUID.randomUUID().toString(),second=UUID.randomUUID().toString();f.cues.begin(first,10);f.cues.save(new TravelCueSession.State(first,TravelCueSession.Phase.STOPPED,now,now+900000,1,0,"Stopped"),10);f.cues.begin(second,11);TravelCueSession.State current=new TravelCueSession.State(second,TravelCueSession.Phase.ARMED,now,now+900000,0,0,"");f.cues.save(current,11);try{f.cues.save(new TravelCueSession.State(first,TravelCueSession.Phase.ERROR,now,now+900000,1,0,"The flashlight could not be released."),10);fail();}catch(IllegalStateException expected){}assertEquals(second,f.cues.last().nonce);assertEquals(TravelCueSession.Phase.ARMED,f.cues.last().phase);}}
 @Test public void legacyTripSaveDisablesAndUnreviewsCuesRatherThanReplayingThem(){try(Fixture f=new Fixture()){TravelPlan t=f.trip();f.repo.save(t,f.cue(t),now);TravelPlan update=f.repo.load(now);update.destination="Asia/Tokyo";f.repo.save(update,now+1000);TravelCuePlan result=f.cues.load(update,now);assertFalse(result.enabled);assertFalse(result.reviewed);assertEquals("Asia/Tokyo",result.destination);assertEquals(update.revision,result.tripRevision);assertNull(result.next(now));}}
 @Test public void failedAttemptCanPersistWithoutInventingWindowAndInvalidRunIsRetained()throws Exception{try(Fixture f=new Fixture()){String nonce=UUID.randomUUID().toString();f.cues.begin(nonce,1);f.cues.save(new TravelCueSession.State(nonce,TravelCueSession.Phase.ERROR,0,0,0,0,"The manual recording changed."),1);assertEquals(0,f.cues.last().start);assertEquals(0,f.cues.last().end);String raw=f.prefs.getString(TravelCueStore.RUN,"");String corrupt=new JSONObject(raw).put("phase","RUNNING").toString();assertTrue(f.prefs.edit().putString(TravelCueStore.RUN,corrupt).commit());try{f.cues.last();fail();}catch(IllegalStateException expected){}assertEquals(corrupt,f.prefs.getString(TravelCueStore.RUN,""));}}
 @Test public void reopenedBusyJournalNeverCreatesAServiceOrRestoresOutput(){try(Fixture f=new Fixture()){TravelPlan t=f.trip();f.repo.save(t,f.cue(t),now);String nonce=UUID.randomUUID().toString();f.cues.begin(nonce,1);f.cues.save(new TravelCueSession.State(nonce,TravelCueSession.Phase.RUNNING,now,now+900000,4,0,""),1);TravelPlans.Factory old=TravelPlans.factory;try{TravelPlans.factory=context->f.prefs;TravelCueSession.State result=TravelCues.control.status(c);assertEquals(TravelCueSession.Phase.INTERRUPTED,result.phase);assertEquals(nonce,result.nonce);assertFalse(TrackingService.running);assertFalse(AlarmService.active);}finally{TravelPlans.factory=old;}}}
 @Test public void alarmAdapterReleasesLateReadyAfterCloseAndRequestsOnlyAlarmPriority(){try(Fixture f=new Fixture()){PhoneTorches.Provider old=PhoneTorches.provider;PhoneTorches.Events[] callback={null};java.util.function.BooleanSupplier[] alive={null};int[] requestClosed={0},handleClosed={0};try{PhoneTorches.provider=(context,kind,current,events)->{assertEquals(PhoneTorchCoordinator.Kind.ALARM,kind);assertTrue(current.getAsBoolean());callback[0]=events;alive[0]=current;return ()->requestClosed[0]++;};AlarmTorch torch=new AlarmTorch(privateContext(f.prefs),()->true);torch.close();assertFalse(alive[0].getAsBoolean());callback[0].ready(new PhoneTorches.Handle(){public void set(boolean on){fail("The adapter must not bypass broker commands");}public void close(){handleClosed[0]++;}});assertEquals(1,requestClosed[0]);assertEquals(1,handleClosed[0]);assertTrue(f.prefs.getAll().isEmpty());}finally{PhoneTorches.provider=old;}}}
 @Test public void alarmAdapterAcquisitionFailureIsContainedAndPrivateErrorIsTruthful(){try(Fixture f=new Fixture()){PhoneTorches.Provider old=PhoneTorches.provider;try{PhoneTorches.provider=(context,kind,alive,events)->{throw new IllegalStateException("Worker unavailable");};new AlarmTorch(privateContext(f.prefs),()->true).close();assertEquals("Alarm flashlight unavailable. Sound and the challenge continue.",f.prefs.getString("lastError",""));}finally{PhoneTorches.provider=old;}}}
 private Context privateContext(SharedPreferences prefs){return new ContextWrapper(c){@Override public Context getApplicationContext(){return this;}@Override public SharedPreferences getSharedPreferences(String name,int mode){return prefs;}};}
}
